package org.nonfood.oilplants.web;
import jakarta.servlet.FilterChain;import jakarta.servlet.http.*;import org.junit.jupiter.api.Test;import org.nonfood.oilplants.web.filter.AuthFilter;import org.nonfood.oilplants.web.filter.CsrfFilter;import java.util.*;import static org.mockito.Mockito.*;
class FilterSecurityTest {
 @Test void guestCannotReachProtectedArea()throws Exception{HttpServletRequest req=mock(HttpServletRequest.class);HttpServletResponse res=mock(HttpServletResponse.class);FilterChain chain=mock(FilterChain.class);when(req.getSession(false)).thenReturn(null);when(req.getContextPath()).thenReturn("");when(req.getRequestURI()).thenReturn("/favorites");new AuthFilter().doFilter(req,res,chain);verify(res).sendRedirect("/login?next=%2Ffavorites");verify(chain,never()).doFilter(req,res);}
 @Test void invalidCsrfTokenStopsPost()throws Exception{HttpServletRequest req=mock(HttpServletRequest.class);HttpServletResponse res=mock(HttpServletResponse.class);HttpSession session=mock(HttpSession.class);FilterChain chain=mock(FilterChain.class);when(req.getSession(true)).thenReturn(session);when(session.getAttribute("csrfToken")).thenReturn("expected-token");when(req.getMethod()).thenReturn("POST");when(req.getParameter("csrfToken")).thenReturn("attacker-token");new CsrfFilter().doFilter(req,res,chain);verify(res).sendError(403,"Invalid CSRF token");verify(chain,never()).doFilter(req,res);}
}
